/*
 * Journal ("Deník", audit F10/SY-5): every piece of syntax the app ran — typed, pasted or
 * generated by a dialog — newest first, with copy, download and "open as syntax".
 * SPDX-License-Identifier: GPL-3.0-or-later
 */
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '../../components/Button';
import { EmptyState } from '../../components/EmptyState';
import { Icon } from '../../components/Icon';
import { IconButton } from '../../components/IconButton';
import { openDialog } from '../../app/actions';
import { downloadBlob } from '../../app/files';
import { SPECS_BY_ID } from '../dialogs/specs';
import { useJournal, type JournalEntry } from '../../store/journal';
import { useSyntax } from '../../store/syntax';
import { useUi } from '../../store/ui';
import { useData } from '../../store/data';
import { useLayout } from './layout';

const SOURCE_ICON: Record<JournalEntry['source'], string> = { syntax: 'code', dialog: 'tune', menu: 'menu', data: 'table', system: 'settings' };

async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

export function JournalPanel() {
  const { t, i18n } = useTranslation();
  const entries = useJournal((s) => s.entries);
  const clear = useJournal((s) => s.clear);
  const toast = useUi((s) => s.toast);
  const [filter, setFilter] = useState<'all' | 'errors'>('all');
  const list = useMemo(() => [...entries].reverse().filter((e) => filter === 'all' || !e.ok), [entries, filter]);
  const fmt = useMemo(() => new Intl.DateTimeFormat(i18n.language, { hour: '2-digit', minute: '2-digit', second: '2-digit' }), [i18n.language]);
  const all = () => useJournal.getState().toSyntax();
  const openAsSyntax = (text: string, title?: string) => {
    useSyntax.getState().add(text, title ?? t('shell.journal.syntaxTitle'));
    useUi.getState().setView('syntax');
  };
  const copied = (ok: boolean) => toast(ok ? t('shell.journal.copied') : t('shell.journal.copyFailed'), { kind: ok ? 'success' : 'error' });

  return (
    <aside className="sh-side sh-journal" aria-labelledby="sh-journal-title">
      <div className="sh-side-head">
        <Icon name="history_edu" />
        <h2 id="sh-journal-title" className="sh-side-title">
          {t('shell.journal.title')}
        </h2>
        <span className="sh-side-count">{entries.length}</span>
        <span className="spacer" />
        <IconButton icon="close" small label={t('common.close')} onClick={() => useLayout.getState().setJournal(false)} />
      </div>
      <p className="sh-side-desc">{t('shell.journal.desc')}</p>
      <div className="sh-journal-actions">
        <Button size="sm" iconStart="content_copy" disabled={!entries.length} onClick={() => void copyText(all()).then(copied)}>
          {t('shell.journal.copyAll')}
        </Button>
        <Button size="sm" iconStart="open_in_new" disabled={!entries.length} onClick={() => openAsSyntax(all())}>
          {t('shell.journal.openAll')}
        </Button>
        <IconButton
          icon="download"
          small
          label={t('shell.journal.download')}
          disabled={!entries.length}
          onClick={() => downloadBlob(`${(useData.getState().title || 'journal').replace(/[^\p{L}\p{N}_-]+/gu, '_')}-journal.sps`, all(), 'text/plain')}
        />
        <IconButton
          icon="delete_sweep"
          small
          label={t('shell.journal.clear')}
          disabled={!entries.length}
          onClick={() => {
            const prev = useJournal.getState().entries;
            clear();
            toast(t('shell.journal.cleared'), { action: { label: t('actions.undo'), run: () => useJournal.getState().load(prev) } });
          }}
        />
      </div>
      {entries.some((e) => !e.ok) && (
        <div className="sh-journal-filter" role="group" aria-label={t('shell.journal.filter')}>
          <button type="button" aria-pressed={filter === 'all'} onClick={() => setFilter('all')}>
            {t('shell.journal.all')}
          </button>
          <button type="button" aria-pressed={filter === 'errors'} onClick={() => setFilter('errors')}>
            {t('shell.journal.errors')}
          </button>
        </div>
      )}
      {list.length === 0 ? (
        <EmptyState compact icon="history_edu" title={t('shell.journal.emptyTitle')} description={t('shell.journal.emptyDesc')} />
      ) : (
        <ol className="sh-journal-list">
          {list.map((e) => {
            const spec = e.specId ? SPECS_BY_ID[e.specId] : undefined;
            return (
              <li key={`${e.time}-${e.syntax.length}`} className={`sh-journal-item ${e.ok ? '' : 'err'}`}>
                <div className="sh-journal-meta">
                  <Icon name={e.ok ? SOURCE_ICON[e.source] : 'error'} size={16} />
                  <span className="sh-journal-what">{spec ? t(spec.title) : t(`shell.journal.source.${e.source}`)}</span>
                  <time className="sh-journal-time" dateTime={new Date(e.time).toISOString()}>
                    {fmt.format(e.time)}
                  </time>
                </div>
                <pre className="sh-journal-code">{e.syntax.trim()}</pre>
                <div className="sh-journal-row-actions">
                  <IconButton icon="content_copy" small label={t('shell.journal.copy')} onClick={() => void copyText(e.syntax.trim()).then(copied)} />
                  <IconButton icon="code" small label={t('shell.journal.toSyntax')} onClick={() => {
                      useSyntax.getState().append(`${e.syntax.trim()}\n`);
                      useUi.getState().setView('syntax');
                    }} />
                  {spec && e.values && <IconButton icon="tune" small label={t('shell.journal.reopen')} onClick={() => openDialog(spec.id, e.values)} />}
                </div>
              </li>
            );
          })}
        </ol>
      )}
    </aside>
  );
}
